export interface WorkSessionClockPayload { clock_qr?:string|null; latitude?:number|null; longitude?:number|null; }
export function workSessionNetWorkSeconds(ws: WorkSession | null | undefined): number { if (!ws || ws.ended_at) return 0; const start = new Date(ws.started_at).getTime(); if (Number.isNaN(start)) return 0; const wall = Math.max(0,(Date.now()-start)/1000); return Math.max(0,wall-(ws.break_seconds_total??0)); }
export function workSessionOpenExceedsContract(ws: WorkSession | null | undefined): boolean { if (!ws || ws.ended_at) return false; if (ws.over_contract===true) return true; const threshold=ws.contract_threshold_minutes??480; const nm=ws.open_duration_minutes; if(nm!=null&&nm>=0)return nm>=threshold; return workSessionNetWorkSeconds(ws)>=threshold*60; }

