  connectWebSocket():void{const user=this.getCurrentUser();if(!user||this.ws)return;this.getWsToken().subscribe({next:r=>{if(user.tenant_id!=null)this.connectWebSocketWithToken(user.tenant_id,r.access_token);},error:()=>{if(user.tenant_id!=null)this.connectWebSocketWithToken(user.tenant_id,null);}});} private connectWebSocketWithToken(tenantId:number,token:string|null):void{if(this.ws)return;let wsUrl=this.wsUrl;if(wsUrl.startsWith('/')){const protocol=window.location.protocol==='https:'?'wss:':'ws:';wsUrl=`${protocol}//${window.location.host}${wsUrl}`;}else if(wsUrl.startsWith('http://'))wsUrl=wsUrl.replace('http://','ws://');else if(wsUrl.startsWith('https://'))wsUrl=wsUrl.replace('https://','wss://');else if(!wsUrl.startsWith('ws://')&&!wsUrl.startsWith('wss://'))wsUrl=`ws://${wsUrl}`;const base=`${wsUrl}/tenant/${tenantId}`;const endpoint=token?`${base}?token=${encodeURIComponent(token)}`:base;this.ws=new WebSocket(endpoint);this.ws.onmessage=e=>{try{const data=JSON.parse(e.data);const isReservation=data?.type&&['new_reservation','reservation_updated','reservation_status','reservation_seated','reservation_finished','reservation_cancelled'].includes(data.type);(isReservation?this.reservationUpdates:this.orderUpdates).next(data);}catch{}};this.ws.onclose=e=>{this.ws=null;if(e.code!==1000&&e.code!==1008)setTimeout(()=>this.connectWebSocket(),3000);};this.ws.onerror=()=>this.ws?.close();} disconnectWebSocket():void{if(this.ws){this.ws.close();this.ws=null;}}
